// The device's read tools against the server's (OpenSpec change
// assistant-device-reads, D1): read.vectors.json is generated by
// `go test ./internal/assistant -run Device -update` from the server's read tools
// over the rows its writes make; here the same writes make this device's rows and
// the same calls run against them.
import 'fake-indexeddb/auto'
import { beforeEach, describe, expect, it } from 'vitest'
import { AGENT_EXCLUSIONS_KEY } from '../agentAccess'
import { db, setMeta, useDatabase } from '../db'
import { setCurrentUserId } from '../sharing'
import { manifest } from './manifest'
import { ArgError, ToolError } from './args'
import { loadSnapshot } from './data'
import { getNote, listNotes, searchNotes } from './readNotes'
import { listFrames, listSlots, listTimeEntries } from './readTime'
import vectors from './read.vectors.json'

type Row = Record<string, unknown> & { _clock: Record<string, { ts: number; device: string }> }

const TABLES: Record<string, 'projects' | 'labels' | 'tasks' | 'notes' | 'timeEntries' | 'frames' | 'slots' | 'userPrefs'> = {
  project: 'projects', label: 'labels', task: 'tasks', note: 'notes', time_entry: 'timeEntries', frame: 'frames', slot: 'slots', user_prefs: 'userPrefs',
}

/** The rows the writes make on a device: every field with its clock, appends in their map. */
function rowsOf(writes: typeof vectors.writes): Map<string, Map<string, Row>> {
  const out = new Map<string, Map<string, Row>>()
  for (const w of writes) {
    const table = out.get(w.entity) ?? new Map<string, Row>()
    out.set(w.entity, table)
    const row = table.get(w.id) ?? ({ id: w.id, _clock: {} } as Row)
    table.set(w.id, row)
    for (const [f, v] of Object.entries(w.fields)) {
      if (f.startsWith('appends.')) row.appends = { ...(row.appends as Record<string, unknown> | undefined), [f.slice(8)]: v }
      else row[f] = v
      row._clock[f] = { ts: w.ts, device: 'dev' }
    }
  }
  return out
}

let n = 0
beforeEach(async () => {
  useDatabase(`device-reads-${Date.now()}-${n++}`)
  await setCurrentUserId(vectors.user)
  for (const [entity, rows] of rowsOf(vectors.writes)) await (db[TABLES[entity]] as unknown as { bulkPut(r: unknown[]): Promise<unknown> }).bulkPut([...rows.values()])
  await setMeta(AGENT_EXCLUSIONS_KEY, vectors.kept_away)
})

const TOOLS: Record<string, (snap: Awaited<ReturnType<typeof loadSnapshot>>, a: Record<string, unknown>, now: number, max: number) => Promise<unknown>> = {
  list_notes: listNotes, search_notes: searchNotes, get_note: getNote, list_time_entries: listTimeEntries, list_frames: listFrames, list_slots: listSlots,
}

describe('read vectors', () => {
  for (const c of vectors.cases as { name: string; tool: string; args: Record<string, unknown>; error?: string; result?: unknown }[]) {
    it(c.name, async () => {
      const snap = await loadSnapshot()
      let got: unknown
      let code = ''
      try {
        got = await TOOLS[c.tool](snap, c.args, vectors.now, manifest.limits.max_items)
      } catch (err) {
        if (err instanceof ArgError) code = 'invalid_arguments'
        else if (err instanceof ToolError) code = err.code || err.message
        else throw err
      }
      expect(code).toBe(c.error ?? '')
      if (!c.error) expect(JSON.parse(JSON.stringify(got))).toEqual(c.result)
    })
  }

  it('covers each new tool', () => {
    expect(new Set(vectors.cases.map((c) => c.tool))).toEqual(new Set(Object.keys(TOOLS)))
  })
})
